package br.com.sagio.lead;
import jakarta.persistence.*; import java.time.Instant; import java.time.LocalDate;
@Entity @Table(name="leads") public class Lead { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,length=120) private String nome; @Column(nullable=false,length=180) private String email; @Column(nullable=false,length=30) private String telefone; @Column(nullable=false,length=120) private String passeio; private LocalDate dataPasseio; @Column(nullable=false) private Integer quantidadePessoas; @Column(nullable=false) private boolean consentimentoLgpd; @Column(nullable=false,updatable=false) private Instant createdAt; protected Lead(){} public Lead(String nome,String email,String telefone,String passeio,LocalDate dataPasseio,Integer quantidadePessoas,boolean consentimentoLgpd){this.nome=nome;this.email=email;this.telefone=telefone;this.passeio=passeio;this.dataPasseio=dataPasseio;this.quantidadePessoas=quantidadePessoas;this.consentimentoLgpd=consentimentoLgpd;this.createdAt=Instant.now();} public Long getId(){return id;} public String getNome(){return nome;} public String getEmail(){return email;} public String getTelefone(){return telefone;} public String getPasseio(){return passeio;} public LocalDate getDataPasseio(){return dataPasseio;} public Integer getQuantidadePessoas(){return quantidadePessoas;} public boolean isConsentimentoLgpd(){return consentimentoLgpd;} public Instant getCreatedAt(){return createdAt;} }